if(n<10) return 0;
long long ans=0; long long pow[20]; pow[0]=1; for(int i=1;i<20;i++) pow[i]=pow[i-1]*10;
long long tmp=n; int digits=0; while(tmp){ digits++; tmp/=10; }
for(int len=2; len<digits; len++){
  for(int d=1; d<=9; d++){
    long long cnt=1; for(int i=0;i<len-1;i++) cnt*=d; ans+=cnt;
  }
}
/* length=digits */
long long p=1; for(int i=1;i<digits;i++) p*=10; long long first=n/p;
for(int d=1; d<first; d++){
  long long cnt=1; for(int i=0;i<digits-1;i++) cnt*=d; ans+=cnt;
}
/* equal first */
int ok=1; long long rem=n%p; long long mult=1; for(int i=0;i<digits-1;i++) mult*=first;
long long add=0; long long cur=rem; for(int i=digits-2;i>=0;i--){ long long base=1; for(int j=0;j<i;j++) base*=10; long long digit=cur/base; if(digit>=first){ ok=0; break; } long long ways=1; for(int j=0;j<i;j++) ways*=first; add += digit*ways; cur%=base; }
if(ok) ans+=add+1; return ans;

